from itertools import islice


def read_rows(lines):
    header_seen = False
    for line in lines:
        if not line.strip():
            continue
        if not header_seen:
            header_seen = True
            continue
        sku, qty, amount = (p.strip() for p in line.split(','))
        yield {'sku': sku, 'qty': int(qty), 'amount': float(amount)}


def filter_rows(rows, min_amount):
    return (r for r in rows if r['amount'] >= min_amount)


def chunked(rows, size):
    if size < 1:
        raise ValueError('size must be >= 1')

    def _chunks():
        it = iter(rows)
        while batch := list(islice(it, size)):
            yield batch
    return _chunks()


# ---------------------------------------------------------------------------
# Test harness (do not change). It feeds lines through a counting generator so
# the tests can see how many source lines your pipeline pulled.
# ---------------------------------------------------------------------------
def run_pipeline(lines, chunk_size, min_amount=0.0, probe=False):
    pulled = {"n": 0}

    def source():
        for line in lines:
            pulled["n"] += 1
            yield line

    chunks = chunked(filter_rows(read_rows(source()), min_amount), chunk_size)
    if probe:
        first = next(iter(chunks))
        return {"first_chunk": first, "lines_pulled": pulled["n"]}
    return [list(c) for c in chunks]
